  if(summary)summary.innerHTML='<div class="reviewstats"><div class="reviewstat"><b>'+esc(m.open||0)+'</b>Open</div><div class="reviewstat"><b>'+esc(m.critical||0)+'</b>Critical</div><div class="reviewstat"><b>'+esc(m.identityReviewRequired||0)+'</b>IDR review</div><div class="reviewstat"><b>'+esc(m.highRiskIdentitySignals||0)+'</b>High-risk IDR</div></div>';
