  gate.textContent='RESTORED · '+assessmentId+' · '+targetOrigin+' · '+a.status;state.textContent=a.status||'RESTORED';
  await loadSecurityWorkspace();await loadSecurityAssets();await loadDefensiveAnalysis();return true
