 const box=document.getElementById('grcIntakeReview'),summary=document.getElementById('grcIntakeSummary'),save=document.getElementById('grcIntakeSaveReviewBtn'),approve=document.getElementById('grcIntakeApproveBtn'),imp=document.getElementById('grcIntakeImportBtn'),rows=data?.proposals||[],meta=data?.intake||data||{};
