async function confirmSecurityFindingProposal(id){const p=(window.__securityFindingProposals||[]).find(x=>x.id===id);if(!p)return;const rationale=(prompt('Analyst rationale for CONFIRMED finding (required)')||'').trim();if(rationale.length<10)return alert('Provide a meaningful analyst rationale.');try{await jf('/api/grc/assessments/'+encodeURIComponent(p.assessment_id)+'/findings/'+encodeURIComponent(p.finding_id)+'/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision:'CONFIRMED',rationale})});grcSecurityHandoffMsg.textContent='Finding confirmed. It may now be governed into Issue, Risk and CAPA.';await loadSecurityHandoffs()}catch(e){grcSecurityHandoffMsg.textContent=e.message}}
async function governSecurityFindingProposal(id){const rootCause=(prompt('Validated root cause / management hypothesis (required; do not invent)')||'').trim();if(rootCause.length<10)return alert('Governance requires a meaningful root-cause statement.');const controls=window.__aegisScopedControls||[];let scopeControlId='';if(controls.length){const menu=controls.slice(0,25).map((x,i)=>(i+1)+'. '+(x.control_key||'CONTROL')+' · '+(x.title||'')).join('\n');const choice=(prompt('Optional authoritative control-gap linkage. Enter control number, or leave blank for no control linkage:\n\n'+menu)||'').trim();if(choice){const n=Number(choice);if(!Number.isInteger(n)||n<1||n>Math.min(25,controls.length))return alert('Select a valid scoped-control number.');scopeControlId=controls[n-1].id}}try{await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/security-finding-proposals/'+encodeURIComponent(id)+'/govern',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rootCause,scopeControlId:scopeControlId||undefined})});grcSecurityHandoffMsg.textContent=scopeControlId?'Authoritative control-linked Issue → Risk → CAPA created. The open issue now contributes to that control\'s readiness gap.':'Authoritative Issue → Risk → CAPA records created from the confirmed finding.';await Promise.allSettled([loadSecurityHandoffs(),selectGrcOrg()])}catch(e){grcSecurityHandoffMsg.textContent=e.message}}
async function rejectSecurityFindingProposal(id){const reason=(prompt('Governance rejection rationale (required)')||'').trim();if(reason.length<10)return alert('Provide a meaningful rejection rationale.');try{await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/security-finding-proposals/'+encodeURIComponent(id)+'/reject',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason})});await loadSecurityHandoffs()}catch(e){grcSecurityHandoffMsg.textContent=e.message}}
async function reviewSecurityHandoff(id,decision){const msg=document.getElementById('grcSecurityHandoffMsg');try{if(msg)msg.textContent='Recording independent security-evidence decision…';await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/security-report-handoffs/'+encodeURIComponent(id)+'/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({decision,note:decision==='ACCEPT_EVIDENCE'?'Accepted as governed technical evidence; control conformity remains separately reviewed.':'Rejected during independent GRC evidence review.'})});if(msg)msg.textContent=decision==='ACCEPT_EVIDENCE'?'Evidence accepted. Enterprise report will include this technical handoff.':'Evidence rejected.';await loadSecurityHandoffs()}catch(e){if(msg)msg.textContent='Security evidence review failed: '+e.message}}
