function mergeDocumentAutofill(results){
 const facts=results.flatMap(r=>r.ok?(r.autofill?.facts||[]).map(f=>({...f,file:r.file})):[]),groups=new Map();
 for(const f of facts){const k=f.kind+'|'+f.field,arr=groups.get(k)||[];arr.push(f);groups.set(k,arr)}
 const merged={};for(const [k,arr] of groups){const values=[...new Set(arr.map(x=>String(x.value||'').trim()).filter(Boolean))];merged[k]={kind:arr[0].kind,field:arr[0].field,value:values.length===1?values[0]:null,conflict:values.length>1,values,sources:arr}}return {facts,merged};
}
function renderDocumentAutofillCoverage(results){const el=document.getElementById('grcIntakeAutofill');if(!el)return;const m=mergeDocumentAutofill(results),rows=Object.values(m.merged);el.innerHTML=(rows.length?'<div class="tablewrap"><table><thead><tr><th>GRC area</th><th>Field</th><th>Autofill value</th><th>Source</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+esc(x.kind)+'</td><td>'+esc(x.field)+'</td><td>'+(x.conflict?'<b>CONFLICT — REVIEW</b><br>'+x.values.map(esc).join(' / '):esc(x.value||'—'))+'</td><td>'+x.sources.map(s=>esc(s.file)+' · line '+esc(String(s.sourceLine||''))).join('<br>')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="muted">No supported labelled GRC fields were found. Nothing was invented.</p>')+'<div class="row u-mt-8">'+results.filter(r=>r.ok).map(r=>'<button class="btn alt" data-action="openGrcIntake" data-id="'+esc(r.id)+'">Review '+esc(r.file)+(r.reused?' · existing':'')+'</button>').join('')+'</div>';
 const unique=(kind,field)=>m.merged[kind+'|'+field]&&!m.merged[kind+'|'+field].conflict?m.merged[kind+'|'+field].value:null,set=(id,v)=>{const x=document.getElementById(id);if(x&&v)x.value=v};
 set('grcScopeName',unique('SCOPE','scopeName'));set('grcScopeDesc',unique('SCOPE','scopeDescription'));set('tprmVendorName',unique('VENDOR','vendorName'));set('tprmVendorKey',unique('VENDOR','vendorKey'));set('tprmVendorService',unique('VENDOR','vendorService'));
 const tier=unique('VENDOR','vendorTier');if(tier)set('tprmVendorTier',String(tier).toUpperCase().replace(/[ -]/g,'_').replace(/^([1-4])$/,'TIER_$1'));set('tprmVendorCriticality',unique('VENDOR','vendorCriticality')?.toUpperCase());
 set('phase3SoaApplicability',unique('CONTROL','applicability')?.toUpperCase().replace(/[ -]/g,'_'));set('phase3SoaImplementation',unique('CONTROL','implementation')?.toUpperCase().replace(/ /g,'_'));set('phase3SoaJustification',unique('CONTROL','justification'));
 set('privacyActivityKey',unique('PRIVACY','activityKey'));set('privacyActivityName',unique('PRIVACY','activityName'));set('privacyPurpose',unique('PRIVACY','processingPurpose'));set('privacyGround',unique('PRIVACY','processingGround'));set('privacyRetention',unique('PRIVACY','retentionRule'));set('privacyLegalKey',unique('LEGAL','legalKey'));set('privacyLegalTitle',unique('LEGAL','legalTitle'));set('privacyLegalSource',unique('LEGAL','legalSource'));
 set('appetiteKey',unique('GOVERNANCE','appetiteKey'));set('appetiteTitle',unique('GOVERNANCE','appetiteTitle'));set('appetiteStatement',unique('GOVERNANCE','appetiteStatement'));set('appetiteTolerance',unique('GOVERNANCE','toleranceRating')?.toUpperCase());set('metricKey',unique('GOVERNANCE','metricKey'));set('metricTitle',unique('GOVERNANCE','metricTitle'));set('metricType',unique('GOVERNANCE','metricType')?.toUpperCase());
}
async function parseGrcIntake(){
 const status=document.getElementById('grcIntakeStatus'),input=document.getElementById('grcIntakeFile'),files=[...(input?.files||[])];if(!activeGrcOrg){if(status)status.textContent='Select or create an Enterprise GRC organization first.';return}if(!files.length){if(status)status.textContent='Choose one or more governance documents first.';return}
 const btn=document.getElementById('grcIntakeParseBtn');if(btn)btn.disabled=true;const results=[];
 try{for(let i=0;i<files.length;i++){const file=files[i];if(status)status.textContent='Parsing '+(i+1)+'/'+files.length+': '+file.name+'…';try{const form=new FormData();form.append('document',file);if(activeGrcScope)form.append('scopeId',activeGrcScope);const r=await fetch('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/document-intakes',{method:'POST',body:form,credentials:'same-origin'});const created=await r.json();if(!r.ok)throw new Error(created.error||'Document intake failed');if(!Number(created.proposalCount||0))throw new Error('Document was stored, but no deterministic GRC facts were extracted. Use labelled fields or a supported structured GRC report and review the parser output before continuing.');const filled=await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/document-intakes/'+encodeURIComponent(created.id)+'/autofill',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});results.push({ok:true,file:file.name,id:created.id,count:created.proposalCount,reused:Boolean(created.reused),scope:filled.scope||null,autofill:filled.autofill||{facts:[]}});}catch(e){results.push({ok:false,file:file.name,error:e.message})}}
 const good=results.filter(x=>x.ok),bad=results.filter(x=>!x.ok);renderDocumentAutofillCoverage(results);if(good.length){activeGrcIntake=good[good.length-1].id;const scoped=good.filter(x=>x.scope);if(scoped.length){activeGrcScope=scoped[scoped.length-1].scope.id;await selectGrcOrg();if(grcScope){grcScope.value=activeGrcScope;grcActiveScope.textContent=scoped[scoped.length-1].scope.name||'Document scope'}}await openGrcIntake(activeGrcIntake)}if(status)status.textContent=good.length+' of '+files.length+' document(s) processed. '+good.reduce((n,x)=>n+(x.count||0),0)+' extracted fact(s).'+(bad.length?' Failed: '+bad.map(x=>x.file+' ('+x.error+')').join('; '):' Existing GRC fields were populated where deterministic document facts were available.')}finally{if(btn)btn.disabled=false}
}
