async function saveSoaDecision(){
 const msg=document.getElementById('soaDecisionMsg'),btn=document.getElementById('saveSoaDecisionBtn');
 const control=document.getElementById('soaControl'),applicabilityEl=document.getElementById('soaApplicability'),implementationEl=document.getElementById('soaImplementation'),justificationEl=document.getElementById('soaJustification');
 const say=value=>{if(msg)msg.textContent=value;const globalMsg=document.getElementById('grcMsg');if(globalMsg)globalMsg.textContent=value};
 if(!activeGrcOrg||!activeGrcScope){say('Select an organization and scope first.');return}
 if(!control?.value){say('Select a canonical control.');return}
 const controlId=control.value,scopeId=activeGrcScope,applicability=applicabilityEl?.value||'PENDING',implementation=implementationEl?.value||'NOT_IMPLEMENTED',justification=String(justificationEl?.value||'').trim();
 if(applicability==='NOT_APPLICABLE'&&justification.length<10){say('Not-applicable controls require a meaningful justification (minimum 10 characters).');return}
 try{
  if(btn){btn.disabled=true;btn.textContent='Saving...'}say('Saving SoA decision...');
  await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/scopes/'+encodeURIComponent(scopeId)+'/controls',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({controlId,applicability,justification,implementation})});
  if(justificationEl)justificationEl.value='';
  await loadSoa();
  say('SoA decision saved successfully.');
 }catch(e){say('SoA save failed: '+e.message)}
 finally{if(btn){btn.disabled=false;btn.textContent='Save SoA Decision'}}
}
