 const request=document.getElementById('grcEvidenceRequest'),note=document.getElementById('grcEvidenceValidationNote'),msg=document.getElementById('grcEvidenceUploadMsg');
 const say=x=>{if(msg)msg.textContent=x};if(!activeGrcOrg)return say('Select an organization first.');if(!request?.value)return say('Select an evidence request first.');
 const option=request.options[request.selectedIndex],versionId=option?.dataset?.versionId,status=option?.dataset?.status;
 if(!versionId)return say('Upload a server-verified evidence version before validation.');if(status!=='SUBMITTED')return say('Only SUBMITTED evidence awaiting review can be validated.');
