async function authorize(){try{if(!activeGrcOrg){await loadGrcWorkspace();if(!activeGrcOrg)return gate.textContent='Select the organization once in Enterprise GRC before starting URL analysis. The same tenant context is reused by Offensive and Defensive Security.';}gate.textContent='Validating authorization and establishing assessment…';const d=await jf('/api/assessment/authorize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({targetUrl:target.value,authorized:auth.checked,organizationId:activeGrcOrg||undefined})});assessmentId=d.assessmentId;targetOrigin=d.targetOrigin;sessionToken=d.sessionToken;gate.textContent='AUTHORIZED · '+assessmentId+' · '+targetOrigin+' · full URL analysis starting';state.textContent='AUTHORIZED';loadDocs();await loadSecurityWorkspace();await loadSecurityAssets();tool.value='all';await scan()}catch(e){gate.textContent=e.message;state.textContent='FAILED'}}
async function quickScan(){if(!assessmentId)return;try{raw.textContent='Running live HTTP posture probe…';const d=await jf('/api/scans/quick',{method:'POST',headers:{'Content-Type':'application/json','x-assessment-session':sessionToken},body:JSON.stringify({targetUrl:targetOrigin})});raw.textContent=JSON.stringify(d,null,2);state.textContent=d.error?'PARTIAL':'LIVE';await report()}catch(e){raw.textContent='LIVE CHECK FAILED · '+e.message;state.textContent='PARTIAL'}}
async function pollFullAssessment(){
 const deadline=Date.now()+6*60*1000;let transientErrors=0;
 while(Date.now()<deadline){
  await new Promise(r=>setTimeout(r,2500));
  try{
   const w=await jf('/api/assessments/'+assessmentId+'/security-workspace');
   const r=await jf('/api/assessments/'+assessmentId+'/report',{headers:{'x-assessment-session':sessionToken}});
   const fs=r.findings||[];renderFindings(fs);const evidenceRows=await loadExecutionEvidence();transientErrors=0;
   const status=String(w.assessment?.status||'RUNNING');
   gate.textContent=status+' · '+assessmentId+' · '+targetOrigin+' · '+Number(w.offensive?.findings||0)+' finding(s) · '+Number(w.offensive?.evidenceRecords||0)+' evidence record(s) · '+evidenceRows.length+' evidence record(s) rendered';
   state.textContent=status==='RUNNING'?'SCANNING':status;
   if(['COMPLETED','PARTIAL','FAILED'].includes(status)){await loadExecutionEvidence();await loadSecurityAssets();return status}
  }catch(e){transientErrors++;raw.textContent='Assessment is still running. Progress refresh temporarily failed ('+transientErrors+'). The server-side scan continues independently.\n\n'+e.message}
 }
 state.textContent='PARTIAL';gate.textContent='ASSESSMENT STILL RUNNING · '+assessmentId+' · browser polling window ended; use Refresh Evidence to continue monitoring.';return 'RUNNING'
}
async function scan(){
 if(!assessmentId||!sessionToken)return raw.textContent='Authorize the target first inside Offensive Security.';
 if(tool.value==='quick')return quickScan();
 try{
  const full=tool.value==='all';
  raw.textContent=full?'SUBMITTING FULL URL ASSESSMENT…':'Executing deep real '+tool.value+' scan…';state.textContent='SCANNING';
  if(full){const box=document.getElementById('urlAnalysisSummary');if(box)box.innerHTML='<div class="capability-card"><b>STARTING</b><small>Submitting authorized assessment</small></div>';gate.textContent='STARTING · '+assessmentId+' · '+targetOrigin}
  const d=await jf('/api/scans/run',{method:'POST',headers:{'Content-Type':'application/json','x-assessment-session':sessionToken},body:JSON.stringify({targetUrl:targetOrigin,tool:tool.value})});
  if(full&&d.status==='RUNNING'){gate.textContent='RUNNING · '+assessmentId+' · '+targetOrigin+' · server-side assessment accepted';raw.textContent='ASSESSMENT ACCEPTED\n\nThe server is executing HTTP posture, Nuclei, bounded Nmap discovery, ZAP, Wapiti and SQLmap. This page now polls persisted PostgreSQL evidence; no long proxy request is held open.';await pollFullAssessment();return}
  raw.textContent=JSON.stringify(d,null,2);state.textContent=full?(d.status==='COMPLETED'?'SCANNED':d.status==='PARTIAL'?'PARTIAL':'FAILED'):(d.exitCode===0?'SCANNED':'FAILED');await report()
 }catch(e){raw.textContent='ASSESSMENT START FAILED · '+e.message;state.textContent='FAILED';gate.textContent='ANALYSIS FAILED · '+e.message;try{await report()}catch{}}
}
