function charts(fs){const cv=document.getElementById('pie'),cx=cv.getContext('2d'),w=cv.width=cv.clientWidth*devicePixelRatio,h=cv.height=cv.clientHeight*devicePixelRatio;cx.scale(devicePixelRatio,devicePixelRatio);const W=cv.clientWidth,H=cv.clientHeight,keys=['CRITICAL','HIGH','MEDIUM','LOW','INFO'],cols=['#ef4444','#f97316','#eab308','#22d3ee','#64748b'],vals=keys.map(k=>fs.filter(f=>f.severity===k).length),total=Math.max(1,vals.reduce((a,b)=>a+b,0));cx.clearRect(0,0,W,H);let a=-Math.PI/2;vals.forEach((v,i)=>{const z=v/total*Math.PI*2;cx.beginPath();cx.moveTo(W*.3,H*.5);cx.arc(W*.3,H*.5,Math.min(W,H)*.28,a,a+z);cx.fillStyle=cols[i];cx.fill();a+=z});cx.fillStyle='#dbeafe';cx.font='14px system-ui';keys.forEach((k,i)=>cx.fillText(k+' '+vals[i],W*.62,48+i*28));const b=document.getElementById('bars'),bx=b.getContext('2d'),bw=b.width=b.clientWidth*devicePixelRatio,bh=b.height=b.clientHeight*devicePixelRatio;bx.scale(devicePixelRatio,devicePixelRatio);const BW=b.clientWidth,BH=b.clientHeight,m=Math.max(1,...vals);vals.forEach((v,i)=>{const x=30+i*(BW-50)/5,hh=v/m*(BH-70);bx.fillStyle=cols[i];bx.fillRect(x,BH-35-hh,(BW-80)/6,hh);bx.fillStyle='#cbd5e1';bx.font='11px system-ui';bx.fillText(String(v),x,BH-42-hh);bx.fillText(keys[i].slice(0,4),x,BH-15)})}
