function evidenceView(e){
 const meta=e&&e.metadata||{},prov=meta.provenance||{};
 const clip=v=>{const s=String(v||'').trim();return s.length>1800?s.slice(0,1800)+'\n… [truncated in workspace; full record remains stored]':s};
 return {
  engine:String(e.source||'unknown').toUpperCase(),
  status:e.exitCode===0?'SUCCEEDED':e.exitCode===null||e.exitCode===undefined?'RECORDED':'FAILED / NON-ZERO',
  exitCode:e.exitCode??null,
  collectedAt:e.createdAt||null,
  sha256:e.sha256||null,
  target:meta.target||prov.sourceRef||null,
  mode:meta.mode||prov.verificationMethod||null,
  trust:meta.evidenceTrust||null,
  provenanceFingerprint:meta.provenanceFingerprint||null,
  limitations:meta.provenanceLimitations||prov.limitations||[],
  stdout:clip(e.stdout),
  stderr:clip(e.stderr)
 };
}
async function loadExecutionEvidence(){
 if(!assessmentId){raw.textContent='Authorize an assessment to load execution evidence.';return []}
 try{
  const ev=await jf('/api/assessments/'+assessmentId+'/evidence');
  const rows=Array.isArray(ev)?ev:[];
  raw.textContent=rows.length?JSON.stringify(rows.map(evidenceView),null,2):'No persisted scanner evidence yet. This does not mean the target is vulnerability-free.';
  return rows
 }catch(e){raw.textContent='Execution evidence temporarily unavailable. Persisted findings are unchanged.\n\n'+e.message;return []}
}
