async function generateSecurityReportToGrc(source,msgId){const msg=document.getElementById(msgId);if(!assessmentId){if(msg)msg.textContent='Authorize and run the URL assessment first.';return}const src=String(source||'').toUpperCase();if(!['OFFENSIVE','DEFENSIVE'].includes(src)){if(msg)msg.textContent='Unsupported security report source.';return}try{if(msg)msg.textContent='Generating '+src+' report from persisted assessment evidence and handing it to Enterprise GRC…';const d=await jf('/api/assessments/'+encodeURIComponent(assessmentId)+'/generated-security-report/'+src,{method:'POST'});if(!d.grcHandoff?.id)throw new Error('Generated report was not confirmed in the GRC evidence queue.');if(msg)msg.textContent=src+' report generated · SHA-256 '+d.report.sha256+' · GRC '+d.grcHandoff.status+(d.reused?' · existing identical report reused':'');if(d.organizationId&&d.organizationId!==activeGrcOrg){const option=[...grcOrg.options].find(o=>o.value===d.organizationId);if(option){grcOrg.value=d.organizationId;await selectGrcOrg()}}if(activeGrcOrg)await loadSecurityHandoffs()}catch(e){if(msg)msg.textContent='Report → GRC failed: '+e.message}}
async function uploadSecurityDocs(inputId,typeId,msgId){if(!assessmentId){const m=document.getElementById(msgId);if(m)m.textContent='Start or reuse an assessment first.';return}const input=document.getElementById(inputId),type=document.getElementById(typeId),msg=document.getElementById(msgId);if(!input?.files?.length){msg.textContent='Choose one or more evidence files.';return}const source=inputId.startsWith('offensive')?'OFFENSIVE':'DEFENSIVE',fd=new FormData();[...input.files].forEach(file=>fd.append('files',file));fd.append('documentType',type.value);fd.append('securitySource',source);fd.append('description',source==='OFFENSIVE'?'Offensive security workspace evidence':'Defensive security workspace evidence');msg.textContent='Hashing, storing and handing '+source+' evidence to Enterprise GRC…';try{const d=await jf('/api/assessments/'+assessmentId+'/documents',{method:'POST',body:fd}),docs=d.documents||[],handed=docs.filter(x=>x.grcHandoff).length;if(handed!==docs.length)throw new Error('Evidence stored but GRC handoff was not confirmed for every uploaded document. Refresh Enterprise GRC before retrying.');msg.textContent=docs.length+' evidence file(s) stored · '+handed+' '+source+' GRC handoff(s) created';input.value='';await loadDocs();await loadSecurityWorkspace();if(d.organizationId&&d.organizationId!==activeGrcOrg){const option=[...grcOrg.options].find(o=>o.value===d.organizationId);if(option){grcOrg.value=d.organizationId;await selectGrcOrg();msg.textContent+=' · Enterprise GRC switched to the assessment organization';}else{msg.textContent+=' · Handoff belongs to organization '+d.organizationId+'; select that organization in Enterprise GRC';}}else if(activeGrcOrg)await loadSecurityHandoffs()}catch(e){msg.textContent=e.message}}
function defensiveActionCard(a,i){const sev=esc(a.severity||'INFO'),cv=a.residualRisk?esc(a.residualRisk):'REVIEW AFTER RETEST',id=esc(a.findingId),source=esc(a.source||'unknown'),status=esc(a.status||'OPEN');return '<article class="defense-remediation-item"><div class="defense-remediation-head"><div><span class="defense-priority">P'+(a.severity==='CRITICAL'||a.severity==='HIGH'?'1':a.severity==='MEDIUM'?'2':'3')+'</span><b> '+esc(a.title)+'</b></div><span class="defense-severity defense-'+String(a.severity||'INFO').toLowerCase()+'">'+sev+'</span></div><div class="defense-asset">'+esc(a.asset||'Unspecified asset')+' · '+source+' · '+status+'</div><div class="defense-step"><strong>MITIGATE / HARDEN</strong><span>'+esc(a.mitigation)+'</span></div><div class="defense-step"><strong>RETEST</strong><span>'+esc(a.validation)+'</span></div><div class="defense-step"><strong>RESIDUAL RISK</strong><span>'+cv+'</span></div><small>Evidence SHA-256 · '+esc(a.evidenceHash||'Not recorded')+'</small><details class="defense-closure"><summary>Review & closure controls</summary><div class="defense-closure-grid"><select id="defenseDecision-'+id+'"><option value="CONFIRMED">Confirmed · keep open</option><option value="FALSE_POSITIVE">False positive</option><option value="ACCEPTED">Residual risk accepted</option><option value="REMEDIATED">Remediated · retest required</option></select><input id="defenseRetest-'+id+'" placeholder="Retest evidence ID (required for REMEDIATED)"><textarea id="defenseRationale-'+id+'" rows="2" placeholder="Analyst rationale (10–4000 characters)"></textarea>'+(String(a.source||'').toLowerCase()==='wazuh'?'<input id="defenseRetestFile-'+id+'" type="file" accept=".json,application/json"><button class="btn alt" data-aegis-click="runWazuhDefensiveRetest(\''+id+'\')">Import Wazuh targeted retest</button>':String(a.source||'').toLowerCase()==='prowler'?'<input id="defenseProwlerRetestFile-'+id+'" type="file" accept=".json,application/json"><select id="defenseProwlerProvider-'+id+'"><option>AWS</option><option>AZURE</option><option>GCP</option></select><input id="defenseProwlerAsset-'+id+'" placeholder="Registered cloud asset ID"><button class="btn alt" data-aegis-click="runProwlerDefensiveRetest(\''+id+'\')">Import Prowler targeted retest</button>':String(a.source||'').toLowerCase()==='openvas'?'<input id="defenseOpenvasRetestFile-'+id+'" type="file" accept=".json,application/json"><button class="btn alt" data-aegis-click="runOpenvasDefensiveRetest(\''+id+'\')">Import OpenVAS targeted retest</button>':String(a.source||'').toLowerCase()==='trivy'?'<input id="defenseTrivyAsset-'+id+'" placeholder="Registered container asset ID"><input id="defenseTrivyImage-'+id+'" placeholder="Container image ref to retest"><button class="btn alt" data-aegis-click="runTrivyDefensiveRetest(\''+id+'\')">Run native Trivy targeted retest</button>':String(a.source||'').toLowerCase()==='semgrep'?'<input id="defenseSemgrepAsset-'+id+'" placeholder="Registered repository asset ID"><button class="btn alt" data-aegis-click="runSemgrepDefensiveRetest(\''+id+'\')">Run native Semgrep targeted retest</button>':String(a.source||'').toLowerCase()==='gitleaks'?'<input id="defenseGitleaksAsset-'+id+'" placeholder="Registered repository asset ID"><button class="btn alt" data-aegis-click="runGitleaksDefensiveRetest(\''+id+'\')">Run native Gitleaks targeted retest</button>':['nmap','wapiti','zap','nuclei'].includes(String(a.source||'').toLowerCase())?'<button class="btn alt" data-aegis-click="runNativeDefensiveRetest(\''+id+'\')">Run native '+source.toUpperCase()+' targeted retest</button>':'')+'<button class="btn" data-aegis-click="reviewDefensiveFinding(\''+id+'\')">Submit governed review</button><button class="btn alt" data-aegis-click="loadDefensiveReviewHistory(\''+id+'\')">Review history</button></div><div id="defenseHistory-'+id+'" class="defense-history muted">Closure is server-gated. AI cannot mark this finding remediated.</div></details></article>'}
async function runWazuhDefensiveRetest(id){const input=document.getElementById('defenseRetestFile-'+id),box=document.getElementById('defenseHistory-'+id),retest=document.getElementById('defenseRetest-'+id);if(!input?.files?.[0]){if(box)box.textContent='Choose a completed Wazuh JSON retest report.';return}const fd=new FormData();fd.append('file',input.files[0]);if(box)box.textContent='Importing Wazuh retest evidence and comparing the original finding fingerprint…';try{const r=await fetch('/api/grc/assessments/'+assessmentId+'/findings/'+id+'/wazuh-retest',{method:'POST',credentials:'same-origin',headers:{'x-assessment-session':sessionToken||''},body:fd});let d={};try{d=await r.json()}catch{};if(r.status===409&&d.stillPresent){if(box)box.textContent='Retest recorded: the same vulnerability/detection fingerprint is still present. Remediation cannot be closed.';await loadDefensiveAnalysis();return}if(!r.ok)throw Error(d.error||'Wazuh retest import failed (HTTP '+r.status+').');if(retest)retest.value=d.evidenceId||'';if(box)box.textContent='Clean targeted retest evidence recorded. Evidence ID '+(d.evidenceId||'')+' is ready for governed REMEDIATED review.';input.value='';await loadDefensiveAnalysis()}catch(e){if(box)box.textContent=e.message}}
async function runProwlerDefensiveRetest(id){const input=document.getElementById('defenseProwlerRetestFile-'+id),assetId=document.getElementById('defenseProwlerAsset-'+id)?.value?.trim()||'',provider=document.getElementById('defenseProwlerProvider-'+id)?.value||'',box=document.getElementById('defenseHistory-'+id),retest=document.getElementById('defenseRetest-'+id);if(!input?.files?.[0]){if(box)box.textContent='Choose a completed Prowler JSON retest report.';return}if(!assetId){if(box)box.textContent='Enter the registered cloud asset ID used by the original finding.';return}const fd=new FormData();fd.append('report',input.files[0]);fd.append('assetId',assetId);fd.append('provider',provider);fd.append('scanCompleted','true');if(box)box.textContent='Importing completed Prowler retest evidence and comparing the original finding fingerprint…';try{const r=await fetch('/api/grc/assessments/'+assessmentId+'/findings/'+id+'/prowler-retest',{method:'POST',credentials:'same-origin',headers:{'x-assessment-session':sessionToken||''},body:fd});let d={};try{d=await r.json()}catch{};if(r.status===409&&d.stillPresent){if(box)box.textContent='Retest recorded: the same Prowler finding fingerprint is still present. Remediation cannot be closed.';await loadDefensiveAnalysis();return}if(!r.ok)throw Error(d.error||'Prowler retest import failed (HTTP '+r.status+').');if(retest)retest.value=d.evidenceId||'';if(box)box.textContent='Clean Prowler targeted retest recorded. Evidence ID '+(d.evidenceId||'')+' is ready for governed REMEDIATED review.';input.value='';await loadDefensiveAnalysis()}catch(e){if(box)box.textContent=e.message}}
