async function runTrivyDefensiveRetest(id){const assetId=document.getElementById('defenseTrivyAsset-'+id)?.value?.trim()||'',imageRef=document.getElementById('defenseTrivyImage-'+id)?.value?.trim()||'',box=document.getElementById('defenseHistory-'+id),retest=document.getElementById('defenseRetest-'+id);if(!assetId||!imageRef){if(box)box.textContent='Enter the registered container asset ID and the image reference to retest.';return}if(box)box.textContent='Running native Trivy retest and comparing the original vulnerability fingerprint…';try{const r=await fetch('/api/grc/assessments/'+assessmentId+'/findings/'+id+'/trivy-retest',{method:'POST',credentials:'same-origin',headers:{'x-assessment-session':sessionToken||'','Content-Type':'application/json'},body:JSON.stringify({assetId,imageRef})});let d={};try{d=await r.json()}catch{};if(r.status===409&&d.stillPresent){if(box)box.textContent='Retest completed: the same Trivy vulnerability fingerprint is still present. Remediation cannot be closed.';await loadDefensiveAnalysis();return}if(!r.ok)throw Error(d.error||'Trivy targeted retest failed (HTTP '+r.status+').');if(retest)retest.value=d.evidenceId||'';if(box)box.textContent='Clean native Trivy retest recorded. Evidence ID '+(d.evidenceId||'')+' is ready for governed REMEDIATED review.';await loadDefensiveAnalysis()}catch(e){if(box)box.textContent=e.message}}
