async function reviewDefensiveFinding(id){const decision=document.getElementById('defenseDecision-'+id)?.value,rationale=document.getElementById('defenseRationale-'+id)?.value||'',retestEvidenceId=document.getElementById('defenseRetest-'+id)?.value?.trim()||'',box=document.getElementById('defenseHistory-'+id);if(!assessmentId)return;if(rationale.trim().length<10){if(box)box.textContent='Enter an analyst rationale of at least 10 characters.';return}const body={decision,rationale};if(decision==='REMEDIATED')body.retestEvidenceId=retestEvidenceId;try{const d=await jf('/api/grc/assessments/'+assessmentId+'/findings/'+id+'/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(box)box.textContent='Recorded: '+d.review.decision+' · '+new Date(d.review.created_at).toLocaleString();await loadDefensiveAnalysis()}catch(e){if(box)box.textContent=e.message}}
