function renderDefensiveAnalysis(d){const plan=document.getElementById('defensivePlan');if(!plan)return;const p=d.posture||{},actions=d.actions||[],life=d.lifecycle||[],hard=d.detectionAndHardening||{},limits=d.limitations||[];plan.innerHTML='<div class="defense-posture-strip"><div><span>OPEN FINDINGS</span><b>'+Number(p.openFindings||0)+'</b></div><div><span>CRITICAL</span><b>'+Number(p.critical||0)+'</b></div><div><span>HIGH</span><b>'+Number(p.high||0)+'</b></div><div><span>EVIDENCE</span><b>'+Number(p.evidenceRecords||0)+'</b></div></div><div class="defense-lifecycle">'+life.map((x,i)=>'<span>'+(i+1)+' · '+esc(x)+'</span>').join('')+'</div><div class="defense-evidence-line"><strong>Evidence sources</strong><span>'+esc((p.evidenceSources||[]).join(', ')||'No persisted source evidence')+'</span></div><div class="defense-section-title">Prioritized remediation & targeted retest</div><div class="defense-remediation-list">'+(actions.length?actions.map(defensiveActionCard).join(''):'<div class="defense-empty">No open evidence-backed findings require a remediation action. This is not proof that untested surfaces are secure.</div>')+'</div><div class="defense-section-title">Detection & hardening guidance</div><div class="defense-guidance"><div><strong>Observed telemetry</strong><span>'+esc((hard.telemetryAvailable||[]).join(', ')||'No supported telemetry source observed')+'</span></div>'+(hard.recommendations||[]).map(x=>'<div><strong>HARDEN</strong><span>'+esc(x)+'</span></div>').join('')+'</div><div class="defense-limitations"><strong>Assurance boundary</strong>'+limits.map(x=>'<span>'+esc(x)+'</span>').join('')+'</div>'}
async function loadDefensiveCatalog(){const box=document.getElementById('defensiveCapabilities');if(!box)return;try{const d=await jf('/api/security/defensive/catalog');let observed='';if(assessmentId){try{const orgId=window.currentOrganizationId||window.organizationId||'';if(orgId){const cv=await jf('/api/grc/organizations/'+encodeURIComponent(orgId)+'/assessments/'+encodeURIComponent(assessmentId)+'/coverage');const rows=Array.isArray(cv)?cv:(cv.layers||cv.coverage||[]);observed='<div class="defense-section-title">Current assessment coverage</div>'+(rows.length?rows.map(x=>'<div class="capability-card"><b>'+esc(x.layer||x.name||'Layer')+'</b><span>'+esc(x.status||'NOT OBSERVED')+'</span><small>Evidence '+Number(x.evidence_count??x.evidenceCount??0)+'</small><small>'+esc(x.reason||x.failure_reason||x.failureReason||'Assessment-derived coverage state')+'</small></div>').join(''):'<div class="defense-empty">No authoritative layer coverage has been recorded for this assessment.</div>')}}catch(e){observed='<div class="defense-empty">Assessment coverage unavailable: '+esc(e.message)+'</div>'}}box.innerHTML=(d.capabilities||[]).map(x=>'<div class="capability-card"><b>'+esc(x.category)+'</b><span>'+esc(x.mode.replaceAll('_',' '))+'</span><small>'+esc((x.engines||[]).join(', '))+'</small><small>'+esc(x.purpose)+'</small></div>').join('')+observed+'<div class="defense-limitations"><strong>Truth boundary</strong><span>'+esc(d.truthBoundary)+'</span></div>'}catch(e){box.innerHTML='<div class="defense-empty">'+esc(e.message)+'</div>'}}
async function loadDefensiveAnalysis(){const plan=document.getElementById('defensivePlan');await loadDefensiveCatalog();if(!assessmentId){if(plan)plan.innerHTML='<div class="defense-empty">Run or reuse an assessment first.</div>';return}try{const d=await jf('/api/assessments/'+assessmentId+'/defensive-analysis');renderDefensiveAnalysis(d);await loadSecurityWorkspace()}catch(e){if(plan)plan.innerHTML='<div class="defense-empty">'+esc(e.message)+'</div>'}}

function selectFramework(id,name){selectedFramework=id;fwTitle.textContent=name+' · Evidence Workspace';fwAssessment.textContent='Framework selected. Click Assess Against Framework to run deterministic evidence-to-control mapping.';} async function assessSelectedFramework(){if(!assessmentId)return fwAssessment.textContent='Authorize and assess a URL first.';if(!selectedFramework)return fwAssessment.textContent='Select a framework first.';fwAssessment.textContent='Running backend framework assessment…';try{const d=await jf('/api/assessments/'+assessmentId+'/framework-assessment/'+selectedFramework);fwAssessment.textContent=JSON.stringify(d,null,2)}catch(e){fwAssessment.textContent=e.message}}
function syncFrameworkReportSelector(){const s=document.getElementById('fwReportFramework');if(!s)return;const catalog=globalThis.__aegisFrameworkCatalog||[];const old=s.value||selectedFramework||'';s.innerHTML='<option value="">Select framework report</option>'+catalog.map(f=>'<option value="'+esc(f.id)+'">'+esc(f.name||f.id)+'</option>').join('');if([...s.options].some(o=>o.value===old))s.value=old}
function downloadFramework(){if(!assessmentId)return alert('Authorize an assessment first');const picker=document.getElementById('fwReportFramework');const framework=picker?.value||selectedFramework;if(!framework)return alert('Select the framework report first');pendingExport={framework,format:fwFormat.value};rpw.value='';rotp.value='';rmsg.textContent='';reauth.classList.remove('hidden');rpw.focus()}
let pendingExport=null;function downloadEnterpriseGrc(){if(!activeGrcOrg||!activeGrcScope)return alert('Select an Enterprise GRC organization and scope first');if(activeGrcIntake&&activeGrcIntakeScope&&activeGrcIntakeScope!==activeGrcScope)return alert('Report blocked: the open document intake belongs to a different GRC scope. Select the intake scope before generating the report.');const fw=document.getElementById('grcHeroFramework')?.value;if(!fw)return alert('Select the framework for this GRC report first');const format=document.getElementById('grcHeroFormat')?.value||'pdf';const reportMode=document.getElementById('grcHeroReportMode')?.value||'enterprise';pendingExport={kind:'enterprise',enterprise:true,combined:reportMode==='combined',framework:fw,format};rpw.value='';rotp.value='';rmsg.textContent='';reauth.classList.remove('hidden');rpw.focus()}function downloadKind(kind){if(!assessmentId)return alert('Authorize an assessment first');pendingExport={kind,format:document.getElementById('fmt-'+kind).value};rpw.value='';rotp.value='';rmsg.textContent='';reauth.classList.remove('hidden');rpw.focus()}function cancelExport(){pendingExport=null;reauth.classList.add('hidden')}async function confirmExport(){if(!pendingExport)return;const {kind,framework,format,enterprise,combined}=pendingExport;const password=rpw.value,code=rotp.value.trim();if(!password||!/^[0-9]{6}$/.test(code)){rmsg.textContent='Enter your current AegisGRC account password and the current 6-digit authenticator code.';return}const path=enterprise?('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/scopes/'+encodeURIComponent(activeGrcScope)+'/enterprise-report.'+encodeURIComponent(format)+'?framework='+encodeURIComponent(framework)+(combined?'&package=combined':'')):framework?('/api/assessments/'+encodeURIComponent(assessmentId)+'/framework-report/'+encodeURIComponent(framework)+'/'+encodeURIComponent(format)):('/api/assessments/'+encodeURIComponent(assessmentId)+'/export/'+encodeURIComponent(kind)+'/'+encodeURIComponent(format));const btn=reauth.querySelector('button');if(btn)btn.disabled=true;rmsg.textContent='Verifying account and preparing report…';try{const r=await fetch(path,{credentials:'same-origin',headers:{'x-assessment-session':sessionToken||'','x-report-password':password,'x-report-totp':code,'Accept':'application/octet-stream'}});if(!r.ok){let d={};try{d=await r.json()}catch{};const reason=d.code||d.reason||'';if(r.status===401&&/SESSION_MISSING|USER_SESSION_MISSING/.test(reason+' '+(d.error||'')))throw Error('Your login session has expired. Sign in again, then retry the export.');if(r.status===401&&/PASSWORD_INVALID/.test(reason+' '+(d.error||'')))throw Error('The account password is incorrect. Use the password for your currently signed-in AegisGRC account, not your computer or email password.');if(r.status===401&&/TOTP_INVALID/.test(reason+' '+(d.error||'')))throw Error('Authenticator code invalid or expired. Enter the newest 6-digit code and check device time.');throw Error(d.error||'Report download failed (HTTP '+r.status+').')}const b=await r.blob();if(!b.size)throw Error('The server returned an empty report.');const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=enterprise?(combined?'AegisGRC-Combined-Assurance-'+activeGrcScope+'.'+format:'AegisGRC-Enterprise-'+activeGrcScope+'.'+format):'aegis-'+String(framework||kind).toLowerCase()+'-'+assessmentId+'.'+format;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);cancelExport()}catch(e){rmsg.textContent=e.message||'Unable to download report. Please retry.'}finally{rpw.value='';rotp.value='';if(btn)btn.disabled=false}}

async function submitCurrentForReview(){if(!assessmentId)return reviewMsg.textContent='Authorize an assessment first.';const fw=reviewFramework.value||selectedFramework;if(!fw)return reviewMsg.textContent='Select a framework.';reviewMsg.textContent='Submitting…';try{const d=await jf('/api/assessments/'+assessmentId+'/grc-reviews/'+encodeURIComponent(fw)+'/submit',{method:'POST'});reviewMsg.textContent='Submitted for independent GRC review · '+d.review.status;await loadReviewCenter()}catch(e){reviewMsg.textContent=e.message}}
function reviewCounts(rs){const n=x=>rs.filter(r=>r.status===x).length;rsSubmitted.textContent=n('SUBMITTED');rsReview.textContent=n('IN_REVIEW');rsChanges.textContent=n('CHANGES_REQUESTED');rsApproved.textContent=n('APPROVED');rsRejected.textContent=n('REJECTED')}
function reviewCard(r,canDecide){const id=esc(r.id),status=esc(r.status),notes=esc(r.consultant_notes||'');return '<div class="reviewitem"><div class="reviewtop"><div><b>'+esc(r.framework)+' · '+esc(r.assessment_id)+'</b><div class="muted">Submitted '+new Date(r.submitted_at).toLocaleString()+(r.reviewed_at?' · Reviewed '+new Date(r.reviewed_at).toLocaleString():'')+'</div></div><span class="reviewbadge '+status+'">'+status.replaceAll('_',' ')+'</span></div>'+(notes?'<p><b>Consultant notes:</b> '+notes+'</p>':'')+(r.status==='APPROVED'?'<div class="approvalSeal">✓ GRC TEAM APPROVED<br><small>Reviewed '+(r.approved_at?new Date(r.approved_at).toLocaleString():'and recorded')+'</small></div>':'')+(canDecide?'<textarea id="notes-'+id+'" placeholder="Consultant review notes / evidence gaps / required actions"></textarea><div class="row"><button class="btn alt" data-action="decideReview" data-id="'+esc(id)+'" data-status="IN_REVIEW">Start Review</button><button class="btn alt" data-action="decideReview" data-id="'+esc(id)+'" data-status="CHANGES_REQUESTED">Request Changes</button><button class="btn alt" data-action="decideReview" data-id="'+esc(id)+'" data-status="REJECTED">Reject</button><button class="btn" data-action="decideReview" data-id="'+esc(id)+'" data-status="APPROVED">Approve</button></div>':'<p class="muted">Decision controls are available only to configured GRC reviewers.</p>')+'</div>'}
async function loadReviewCenter(){if(!assessmentId){reviewQueue.innerHTML='<p class="muted">Authorize an assessment to view or submit its GRC review.</p>';reviewCounts([]);return}let own=[];try{const d=await jf('/api/assessments/'+assessmentId+'/grc-reviews');own=d.reviews||[]}catch(e){reviewQueue.textContent=e.message;return}reviewCounts(own);try{const q=await jf('/api/grc-review-queue');reviewQueue.innerHTML=(q.reviews||[]).length?q.reviews.map(r=>reviewCard(r,true)).join(''):'<p class="muted">No reports are waiting for review.</p>';reviewCounts(q.reviews||[])}catch(e){reviewQueue.innerHTML=own.length?own.map(r=>reviewCard(r,false)).join(''):'<p class="muted">No review submitted for this assessment yet.</p>'}}
async function decideReview(id,status){const el=document.getElementById('notes-'+id),notes=el?el.value:'';if((status==='CHANGES_REQUESTED'||status==='REJECTED')&&!notes.trim())return alert('Consultant notes are required for this decision.');try{await jf('/api/grc-reviews/'+id+'/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status,notes})});reviewMsg.textContent='Review decision recorded: '+status.replaceAll('_',' ');await loadReviewCenter()}catch(e){reviewMsg.textContent=e.message}}

function auditTraceCard(x){const latest=(x.reviews||[]).at(-1),issue=x.issue,risks=x.risks||[],capas=x.capa||[];return '<div class="reviewitem"><div class="reviewtop"><div><b>'+esc(x.severity||'INFO')+' · '+esc(x.title||x.findingId)+'</b><div class="muted">'+esc(x.source||'unknown')+' · '+esc(x.findingId)+'</div></div><span class="reviewbadge '+esc(latest?.decision||'SUBMITTED')+'">'+esc(latest?.decision||'UNREVIEWED')+'</span></div><p><b>Evidence SHA-256:</b> <span class="u-break-all">'+esc(x.evidenceHash||'Not linked')+'</span></p><p><b>Issue:</b> '+esc(issue?.issue_key||'Not promoted')+(issue?' · '+esc(issue.status)+' · '+esc(issue.priority):'')+'</p><p><b>Enterprise risk:</b> '+(risks.length?risks.map(r=>esc(r.risk_key)+' · '+esc(r.inherent_rating||r.status)).join(' | '):'Not linked')+'</p><p><b>CAPA / retest:</b> '+(capas.length?capas.map(c=>esc(c.capa_key)+' · '+esc(c.status)+(c.retest_run_id?' · retest '+esc(c.retest_run_id):'')).join(' | '):'Not linked')+'</p></div>'}
function renderBreachImpact(rows){if(!rows||!rows.length)return '<p class="muted">No evidence-derived breach-impact decisions are recorded for this assessment.</p>';return '<div class="u-overflow-auto"><table class="u-data-table"><thead><tr><th class="u-th-plain">Status</th><th class="u-th-plain">Impact</th><th class="u-th-plain">Asset</th><th class="u-th-plain">Evidence</th><th class="u-th-plain">Review</th><th class="u-th-plain">Fingerprint</th></tr></thead><tbody>'+rows.map(x=>'<tr><td class="u-td-top">'+esc(grcEmpty(x.status))+'</td><td class="u-td-top">'+esc(grcEmpty(x.impact_band))+' · '+Number(x.impact_score||0)+'</td><td class="u-td-top">'+esc(grcEmpty(x.asset_id))+'</td><td class="u-td-top">'+(Array.isArray(x.evidence)?x.evidence.length:0)+'</td><td class="u-td-top">'+(x.requires_human_review?'REQUIRED':'Not triggered')+'</td><td class="u-td-top"><code>'+esc(String(x.fingerprint||'').slice(0,16))+'…</code></td></tr>').join('')+'</tbody></table></div>'}
async function loadAuditTrace(){if(!assessmentId){auditTraceMsg.textContent='Authorize an assessment first.';auditTraceRows.innerHTML='<p class="muted">No assessment selected.</p>';return}auditTraceMsg.textContent='Loading authenticated trace…';try{const d=await jf('/api/grc/assessments/'+assessmentId+'/traceability');const s=d.summary||{},stats=[['evidence','Evidence'],['findings','Findings'],['confirmed','Confirmed'],['issues','Issues'],['capa','CAPA'],['breachAssessmentsRequiringReview','Breach Review']];auditTraceStats.innerHTML=stats.map(([k,n])=>'<div class="reviewstat"><b>'+Number(s[k]||0)+'</b>'+n+'</div>').join('');auditTraceRows.innerHTML=(d.chains||[]).length?d.chains.map(auditTraceCard).join(''):'<p class="muted">No findings are recorded for this assessment.</p>';breachImpactRows.innerHTML=renderBreachImpact(d.breachImpactAssessments||[]);auditTraceMsg.textContent=d.assuranceBoundary||'Trace loaded.'}catch(e){auditTraceMsg.textContent=e.message;auditTraceRows.textContent='Unable to load traceability.'}}
async function downloadAuditPackage(format){if(!assessmentId)return alert('Authorize an assessment first');try{const q=await jf('/api/assessments/'+assessmentId+'/grc-reviews');const approved=(q.reviews||[]).filter(x=>x.status==='APPROVED').sort((a,b)=>new Date(b.approved_at)-new Date(a.approved_at))[0];if(!approved)throw new Error('Independent GRC approval is required before authenticated audit export. Submit the assessment in GRC Consultant Review Center first.');const v=await jf('/api/assessments/'+assessmentId+'/grc-reviews/'+approved.id+'/verify');if(!v.valid)throw new Error(v.snapshotCurrent===false?'Approved report is stale because governed assessment data changed. Resubmit it for review.':'GRC approval signature could not be verified.');const r=await fetch('/api/grc/assessments/'+assessmentId+'/audit-package.'+format+'?reviewId='+encodeURIComponent(approved.id),{credentials:'same-origin'});if(!r.ok){let d={};try{d=await r.json()}catch{};throw new Error(d.error||'Audit export failed')}const b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='AegisGRC-Authenticated-Audit-'+assessmentId+'.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);auditTraceMsg.textContent='Authenticated audit package generated from approved snapshot '+approved.snapshot_digest+'.'}catch(e){auditTraceMsg.textContent=e.message}}

async function uploadDocs(){if(!assessmentId)return alert('Authorize an assessment first');if(targetOrigin&&docs.files.length){const combine=confirm('A URL is already active.\n\nOK: combine URL and document evidence in the same assessment/report.\nCancel: keep them separate.');if(!combine){docs.value='';docmsg.textContent='Not combined. Start a separate document assessment if you want document-only scope.';return}}const fd=new FormData();[...docs.files].forEach(f=>fd.append('files',f));docmsg.textContent='Uploading…';try{const d=await jf('/api/assessments/'+assessmentId+'/documents',{method:'POST',body:fd});docmsg.textContent=d.documents.length+' file(s) securely stored as assessment evidence';docs.value='';loadDocs()}catch(e){docmsg.textContent=e.message}}
async function loadDocs(){if(!assessmentId)return;try{const ds=await jf('/api/assessments/'+assessmentId+'/documents');doclist.innerHTML=ds.length?ds.map(d=>'<div class="docrow"><div><b>'+esc(d.filename)+'</b><br><small class="muted">Verified assessment evidence</small></div><div>'+Math.ceil(d.size/1024)+' KB</div><div>'+new Date(d.createdAt).toLocaleString()+'</div><div><button class="btn" data-action="securityAssessDoc" data-id="'+esc(d.id)+'">Security Assess</button> <button class="btn alt" data-action="getDoc" data-id="'+esc(d.id)+'">Download</button> <button class="btn alt" data-action="delDoc" data-id="'+esc(d.id)+'">Delete</button></div></div>').join(''):'<p class="muted">No evidence documents stored.</p>'}catch(e){doclist.textContent=e.message}}
async function securityAssessDoc(id){docmsg.textContent='Running evidence-backed document security assessment…';try{const d=await jf('/api/assessments/'+assessmentId+'/documents/'+id+'/security-assess',{method:'POST'});docmsg.textContent='Complete: '+(d.defensive?.findings||[]).length+' evidence-backed finding(s)';raw.textContent=JSON.stringify(d.offensive,null,2);const plan=document.getElementById('defensivePlan');if(plan)plan.textContent=JSON.stringify({defensive:d.defensive,remediation:d.remediation,limitations:d.limitations},null,2);await report();await loadDefensiveAnalysis()}catch(e){docmsg.textContent=e.message}}
async function analyzeDoc(id){docmsg.textContent='Analyzing evidence…';try{const d=await jf('/api/assessments/'+assessmentId+'/documents/'+id+'/analyze',{method:'POST'});docmsg.textContent='Analysis complete';const plan=document.getElementById('defensivePlan');if(plan)plan.textContent=JSON.stringify(d,null,2);await loadDefensiveAnalysis()}catch(e){docmsg.textContent=e.message}}
function esc(s){return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}function getDoc(id){location.href='/api/assessments/'+assessmentId+'/documents/'+id}async function delDoc(id){if(!confirm('Delete this evidence document? The deletion is audited.'))return;await jf('/api/assessments/'+assessmentId+'/documents/'+id,{method:'DELETE'});loadDocs()}
let cpVoice=false,aiWelcomed=false,aiHistory=[];
function currentWorkspace(){const active=document.querySelector('.section.active');return active?.id||'overview'}
function workspaceLabel(id){return ({overview:'Dashboard',offensive:'Offensive Security',defensive:'Defensive Security',incidents:'Incident Response & IDR',grcops:'Enterprise GRC',architecture:'Architecture Studio',grcreview:'Reviews & Approvals',audittrace:'Audit Traceability',learning:'Learning Hub'})[id]||id}
function updateAiContext(){const label=workspaceLabel(currentWorkspace()),el=document.getElementById('aiWorkspaceContext');if(el)el.textContent=label;return label}
function openCopilot(prompt=''){copilot.classList.add('open');document.getElementById('aiNudge')?.classList.add('hidden');updateAiContext();if(!aiWelcomed){aiWelcomed=true;setTimeout(()=>cpadd('ai','I’m connected to the '+updateAiContext()+' context. Ask for a risk briefing, evidence gaps, architecture guidance, or an explanation of what you see.'),180)}if(prompt){cpq.value=prompt;setTimeout(()=>askCopilot(),100)}setTimeout(()=>cpq?.focus(),160)}
function closeCopilot(){copilot.classList.remove('open')}
function cpadd(kind,s){const d=document.createElement('div');d.className='msg '+kind;const a=document.createElement('span');a.className='msg-avatar';a.textContent=kind==='ai'?'✦':'YOU';const body=document.createElement('div');body.textContent=s;d.append(a,body);cpmsgs.appendChild(d);cpmsgs.scrollTop=cpmsgs.scrollHeight;return body}
async function askCopilot(){const q=cpq.value.trim();if(!q)return;openCopilot();cpadd('user',q);cpq.value='';aiHistory.push({role:'user',content:q});aiHistory=aiHistory.slice(-8);const typing=document.getElementById('aiTyping');typing?.classList.remove('hidden');try{const d=await jf('/api/copilot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,mode:cpmode.value,assessmentId:assessmentId||null,workspaceContext:{workspace:updateAiContext(),organizationId:activeGrcOrg||'',scopeId:activeGrcScope||'',architectureSelection:document.getElementById('architectureInspectorTitle')?.textContent||''},history:aiHistory.slice(-8)})});typing?.classList.add('hidden');const answer=d.text||d.message||'No reply returned.';cpadd('ai',answer);aiHistory.push({role:'assistant',content:answer});aiHistory=aiHistory.slice(-8);if(cpVoice&&d.text&&window.speechSynthesis){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(d.text.slice(0,4000)))}}catch(e){typing?.classList.add('hidden');cpadd('ai','Assistant unavailable: '+e.message)}}
function toggleVoice(){cpVoice=!cpVoice;voiceBtn.textContent=cpVoice?'Voice ON':'Voice'}
function listenCopilot(){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R)return cpadd('ai','Voice recognition is unavailable in this browser. Type the question instead.');const r=new R();r.lang=navigator.language||'en-US';r.onresult=e=>{cpq.value=e.results[0][0].transcript;askCopilot()};r.start()}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-ai-prompt]');if(!b)return;e.preventDefault();openCopilot(b.getAttribute('data-ai-prompt')||'')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&copilot?.classList.contains('open'))closeCopilot();if(e.key==='Enter'&&document.activeElement===cpq&&!e.shiftKey){e.preventDefault();askCopilot()}});
setTimeout(()=>{const n=document.getElementById('aiNudge');if(n&&!copilot.classList.contains('open'))n.classList.add('show')},2200);
function sparkle(){/* Decorative animation disabled for production responsiveness. */}
function ambient(){const c=document.getElementById('ambientbg');if(c)c.style.display='none'/* Decorative animation disabled for production responsiveness. */}
(async()=>{let s;try{s=await jf('/api/auth/status')}catch(e){console.error('Authentication check failed',e);location.replace('/');return}if(!s.authenticated){location.replace('/');return}try{await showApp()}catch(e){console.error('Workspace initialization degraded',e);app?.classList.remove('hidden');copilot?.classList.remove('hidden')}try{await loadOffensiveCatalog()}catch(e){console.warn('Offensive catalog unavailable',e)}})();


