async function loadIso42001AuditEvidence(){const msg=document.getElementById('aimsAuditMsg'),out=document.getElementById('aimsAuditEvidence');if(!activeGrcOrg)return msg.textContent='Select an Enterprise GRC organization first.';try{const path='/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/iso42001/audit-evidence-readiness'+(activeGrcScope?'?scopeId='+encodeURIComponent(activeGrcScope):'');const d=await jf(path);msg.textContent=d.summary.evidenced+'/'+d.summary.total+' request categories have matching records; this is not an audit pass.';out.innerHTML=grcTable(d.requests,[['Evidence request','title'],['Readiness','status'],['Matching records','supportingRecords']]);await loadAimsAudits()}catch(e){msg.textContent=e.message}}
async function createIso42001Audit(){const msg=document.getElementById('aimsAuditMsg');if(!activeGrcOrg)return msg.textContent='Select an Enterprise GRC organization first.';const key=document.getElementById('aimsAuditKey').value.trim();if(!key)return msg.textContent='Enter a unique audit key.';try{const d=await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/iso42001/audit-playbook',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({auditKey:key,scopeId:activeGrcScope||null})});msg.textContent='Created '+d.audit_key+' with '+d.workpapersCreated+' NOT_TESTED workpapers. Auditor sampling and independent review remain required.';await loadIso42001AuditEvidence();await loadAimsAudits();document.getElementById('aimsAuditSelect').value=d.id;await loadAimsAuditWorkpapers()}catch(e){msg.textContent=e.message}}

async function loadAimsAudits(){if(!activeGrcOrg)return;const d=await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/audits'+(activeGrcScope?'?scopeId='+encodeURIComponent(activeGrcScope):''));const sel=document.getElementById('aimsAuditSelect'),old=sel.value;sel.innerHTML='<option value="">Select AIMS audit</option>'+(d.audits||[]).filter(a=>/42001|CSA AICM|NIST SP 800-53/.test(String(a.criteria||''))).map(a=>'<option value="'+esc(a.id)+'">'+esc(a.audit_key)+' · '+esc(a.status)+'</option>').join('');if([...sel.options].some(x=>x.value===old))sel.value=old}
async function loadAimsAuditWorkpapers(){const msg=document.getElementById('aimsAuditMsg'),id=document.getElementById('aimsAuditSelect').value;if(!id)return msg.textContent='Select an AIMS audit.';try{const d=await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/audits/'+encodeURIComponent(id)+'/workpapers');document.getElementById('aimsAuditWorkpapers').innerHTML=grcTable(d.workpapers||[],[['Workpaper','title'],['Result','result'],['Reviewed at','reviewed_at']]);document.getElementById('aimsWorkpaperSelect').innerHTML='<option value="">Select workpaper</option>'+(d.workpapers||[]).map(x=>'<option value="'+esc(x.id)+'">'+esc(x.title)+' · '+esc(x.result)+(x.reviewed_at?' · REVIEWED':'')+'</option>').join('');msg.textContent=(d.workpapers||[]).length+' audit workpapers loaded.'}catch(e){msg.textContent=e.message}}
async function saveAimsAuditWorkpaper(){const msg=document.getElementById('aimsAuditMsg'),id=document.getElementById('aimsWorkpaperSelect').value;if(!id)return msg.textContent='Select a workpaper.';try{await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/audit-workpapers/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({result:document.getElementById('aimsWorkpaperResult').value,conclusion:document.getElementById('aimsWorkpaperConclusion').value,sampleDescription:document.getElementById('aimsWorkpaperSample').value,evidenceRefs:document.getElementById('aimsWorkpaperEvidence').value.split(',').map(x=>x.trim()).filter(Boolean)})});msg.textContent='Workpaper saved; a different authorized reviewer must review it.';await loadAimsAuditWorkpapers()}catch(e){msg.textContent=e.message}}
async function reviewAimsAuditWorkpaper(){const msg=document.getElementById('aimsAuditMsg'),id=document.getElementById('aimsWorkpaperSelect').value;if(!id)return msg.textContent='Select a workpaper.';try{await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/audit-workpapers/'+encodeURIComponent(id)+'/review',{method:'POST'});msg.textContent='Independent workpaper review recorded.';await loadAimsAuditWorkpapers()}catch(e){msg.textContent=e.message}}
async function advanceAimsAudit(){const msg=document.getElementById('aimsAuditMsg'),id=document.getElementById('aimsAuditSelect').value;if(!id)return msg.textContent='Select an AIMS audit.';try{await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/audits/'+encodeURIComponent(id)+'/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:document.getElementById('aimsAuditStatus').value})});msg.textContent='Audit stage advanced.';await loadAimsAudits();document.getElementById('aimsAuditSelect').value=id;await loadAimsAuditWorkpapers();await loadIso42001AuditEvidence()}catch(e){msg.textContent=e.message}}

async function createCsaAicmAudit(){const msg=document.getElementById('aimsAuditMsg');if(!activeGrcOrg)return msg.textContent='Select an Enterprise GRC organization first.';const key=document.getElementById('aimsAuditKey').value.trim();if(!key)return msg.textContent='Enter a unique audit key.';try{const d=await jf('/api/grc/organizations/'+encodeURIComponent(activeGrcOrg)+'/csa-aicm/audit-playbook',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({auditKey:key,scopeId:activeGrcScope||null})});msg.textContent='Created CSA AICM domain-level audit '+d.audit_key+' with '+d.workpapersCreated+' NOT_TESTED workpapers. Official AI-CAIQ/control-level verification is separate.';await loadAimsAudits();document.getElementById('aimsAuditSelect').value=d.id;await loadAimsAuditWorkpapers()}catch(e){msg.textContent=e.message}}

